  "packet_id": "H6-T02-2",
  "claim_id": "C019",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C019",
    "value": "Contradictory evidence should receive priority over counts of supporting evidence items.",
    "scope": "A comparative evaluation priority, not a numerical weighting rule or automatic elimination rule.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 explicitly establishes this evaluation priority."
    }
  },
  "signal_basis": {
    "component_id": "C019_SIGNAL",
    "value": "Comparison identifies reliable, diagnostically important inconsistencies, such as short queue waits conflicting with queue congestion as the direct source of an hour-long export. Evidence items are assessed for reliability and diagnostic value, without counting dependent symptoms as independent support.",
    "scope": "Priority applies to comparative assessment; elimination requires adequate testing of a necessary prediction within the relevant scope.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P010",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the evidence assessment, concrete contradiction, dependence restriction and scope of weakening or elimination."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C019_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The judgment is SUPPORTED; no unresolved empirical relation is required."
    }
  },
  "rationale": "Within the stated limits, reliable diagnostic contradictions warrant priority over raw support counts: counts alone do not establish diagnostic strength or independence. The claim prescribes an evaluation priority without making every contradiction decisive or authorizing automatic elimination.",
  "uncertainty": "The priority does not guarantee that the resulting ranking is correct; its application depends on the stipulated reliability and diagnostic importance of the evidence.",
  "anomalies": []
}
